mapper.select:
select td.id, td.title, td.title_img titleImg,  td.is_recommend isRecommend,
td.classify_id classifyId,
td.details, td.del_status delStatus, td.status, td.play_count playCount,
td.like_count likeCount,  td.is_price isPrice,td.is_end isEnd, td.create_time createTime,
td.up_time upTime, td.update_time updateTime,tdc.name className
from t_drama td
left join t_drama_category tdc on tdc.id=td.classify_id
where td.del_status=1
and td.title like concat('%', #{title}, '%')
and td.title_img = #{titleImg}
and td.is_recommend = #{isRecommend}
and td.classify_id = #{classifyId}
and td.details = #{details}
and td.del_status = #{delStatus}
and td.status = #{status}
and td.play_count = #{playCount}
and td.like_count = #{likeCount}
and td.is_price = #{isPrice}
and td.is_end = #{isEnd}
and td.up_time = #{upTime}
order by td.create_time desc

mapper.update:
update t_drama
title = #{title}, title_img = #{titleImg}, is_recommend = #{isRecommend}, classify_id = #{classifyId}, details = #{details}, del_status = #{delStatus}, status = #{status}, play_count = #{playCount}, like_count = #{likeCount}, is_price = #{isPrice}, is_end = #{isEnd}, create_time = #{createTime}, up_time = #{upTime}, update_time = #{updateTime},
where id = #{id}
